class MSACL(GeneralRecommender):
    def __init__(self, config, dataset):
        super(MSACL, self).__init__(config, dataset)

        num_user = self.n_users
        num_item = self.n_items
        batch_size = config['train_batch_size']  # not used
        dim_x = config['embedding_size']
        self.feat_embed_dim = config['feat_embed_dim']
        self.n_layers = config['n_mm_layers']
        self.knn_k = config['knn_k']
        self.mm_image_weight = config['mm_image_weight']

        self.alpha_item_co = config['alpha_item_co']
        self.lambda_spec = config['lambda_spec']
        self.beta_lf = config['beta_lf']
        self.beta_hf = config['beta_hf']
        self.beta_mix = config['beta_mix']
        self.spec_gate_tau = config['spec_gate_tau']
        self.enable_spec_gate = config['enable_spec_gate']

        if isinstance(self.alpha_item_co, list):
            self.alpha_item_co = self.alpha_item_co[0]
        if isinstance(self.lambda_spec, list):
            self.lambda_spec = self.lambda_spec[0]

        self.batch_size = batch_size
        self.num_user = num_user
        self.num_item = num_item
        self.k = 40
        self.aggr_mode = 'add'
        self.dataset = dataset
        self.dropout = config['dropout']
        self.reg_weight = config['reg_weight']
        self.align_weight = config['align_weight']
        self.layer_agcl_weight = config['layer_agcl_weight']
        self.mask_weight_f = config['mask_weight_f']
        self.temp = config['temp']
        self.alpha = config['alpha']
        self.drop_rate = 0.1
        self.v_rep = None
        self.t_rep = None
        self.v_preference = None
        self.t_preference = None
        self.id_preference = None
        self.dim_latent = 64
        self.dim_feat = 128
        self.mm_adj = None

        self.mlp = nn.Linear(2*dim_x, 2*dim_x)

        dataset_path = os.path.abspath(config['data_path'] + config['dataset'])
        self.user_graph_dict = np.load(os.path.join(dataset_path, config['user_graph_dict_file']),
                                       allow_pickle=True).item()

        if self.v_feat is not None:
            self.image_embedding = nn.Embedding.from_pretrained(self.v_feat, freeze=False)
        if self.t_feat is not None:
            self.text_embedding = nn.Embedding.from_pretrained(self.t_feat, freeze=False)

        self.mm_adj = self.build_and_cache_item_graphs_schemeA(
                k_sem=self.knn_k, 
                k_co=self.knn_k, 
                alpha_item_co=self.alpha_item_co, 
                cache_dir=dataset_path
            )

        # packing interaction in training into edge_index
        train_interactions = dataset.inter_matrix(form='coo').astype(np.float32)
        edge_index = self.pack_edge_index(train_interactions)
        self.edge_index = torch.tensor(edge_index, dtype=torch.long).t().contiguous().to(self.device)
        self.edge_index = torch.cat((self.edge_index, self.edge_index[[1, 0]]), dim=1)

        # pdb.set_trace()
        self.weight_u = nn.Parameter(nn.init.xavier_normal_(
            torch.tensor(np.random.randn(self.num_user, 2, 1), dtype=torch.float32, requires_grad=True)))
        self.weight_u.data = F.softmax(self.weight_u, dim=1)

        self.weight_i = nn.Parameter(nn.init.xavier_normal_(
            torch.tensor(np.random.randn(self.num_item, 2, 1), dtype=torch.float32, requires_grad=True)))
        self.weight_i.data = F.softmax(self.weight_i, dim=1)

        self.item_index = torch.zeros([self.num_item], dtype=torch.long)
        index = []
        for i in range(self.num_item):
            self.item_index[i] = i
            index.append(i)
        self.drop_percent = self.drop_rate
        self.single_percent = 1
        self.double_percent = 0

        drop_item = torch.tensor(
            np.random.choice(self.item_index, int(self.num_item * self.drop_percent), replace=False))
        drop_item_single = drop_item[:int(self.single_percent * len(drop_item))]

        self.dropv_node_idx_single = drop_item_single[:int(len(drop_item_single) * 1 / 3)]
        self.dropt_node_idx_single = drop_item_single[int(len(drop_item_single) * 2 / 3):]

        self.dropv_node_idx = self.dropv_node_idx_single
        self.dropt_node_idx = self.dropt_node_idx_single

        mask_cnt = torch.zeros(self.num_item, dtype=int).tolist()
        for edge in edge_index:
            mask_cnt[edge[1] - self.num_user] += 1
        mask_dropv = []
        mask_dropt = []
        for idx, num in enumerate(mask_cnt):
            temp_false = [False] * num
            temp_true = [True] * num
            mask_dropv.extend(temp_false) if idx in self.dropv_node_idx else mask_dropv.extend(temp_true)
            mask_dropt.extend(temp_false) if idx in self.dropt_node_idx else mask_dropt.extend(temp_true)

        edge_index = edge_index[np.lexsort(edge_index.T[1, None])]
        edge_index_dropv = edge_index[mask_dropv]
        edge_index_dropt = edge_index[mask_dropt]

        self.edge_index_dropv = torch.tensor(edge_index_dropv).t().contiguous().to(self.device)
        self.edge_index_dropt = torch.tensor(edge_index_dropt).t().contiguous().to(self.device)

        self.edge_index_dropv = torch.cat((self.edge_index_dropv, self.edge_index_dropv[[1, 0]]), dim=1)
        self.edge_index_dropt = torch.cat((self.edge_index_dropt, self.edge_index_dropt[[1, 0]]), dim=1)

        self.MLP_user = nn.Linear(self.dim_latent * 2, self.dim_latent)

        if self.v_feat is not None:
            self.v_gcn = GCN(self.dataset, batch_size, num_user, num_item, dim_x, self.aggr_mode, dim_latent=64,
                             device=self.device, features=self.v_feat)
        if self.t_feat is not None:
            self.t_gcn = GCN(self.dataset, batch_size, num_user, num_item, dim_x, self.aggr_mode, dim_latent=64,
                             device=self.device, features=self.t_feat)


        self.id_feat = nn.Parameter(
            nn.init.xavier_normal_(torch.tensor(np.random.randn(self.n_items, self.dim_latent), dtype=torch.float32,
                                                requires_grad=True), gain=1).to(self.device))
        self.id_gcn = GCN(self.dataset, batch_size, num_user, num_item, dim_x, self.aggr_mode,
                          dim_latent=64, device=self.device, features=self.id_feat)


        self.result_embed = nn.Parameter(
            nn.init.xavier_normal_(torch.tensor(np.random.randn(num_user + num_item, dim_x)))).to(self.device)

        self.result_embed_guide = nn.Parameter(
            nn.init.xavier_normal_(torch.tensor(np.random.randn(num_user + num_item, dim_x)))).to(self.device)
        self.result_embed_v = nn.Parameter(
            nn.init.xavier_normal_(torch.tensor(np.random.randn(num_user + num_item, dim_x)))).to(self.device)
        self.result_embed_t = nn.Parameter(
            nn.init.xavier_normal_(torch.tensor(np.random.randn(num_user + num_item, dim_x)))).to(self.device)


    def pre_epoch_processing(self):
        self.epoch_user_graph, self.user_weight_matrix = self.topk_sample(self.k)
        self.user_weight_matrix = self.user_weight_matrix.to(self.device)

    def pack_edge_index(self, inter_mat):
        rows = inter_mat.row
        cols = inter_mat.col + self.n_users
        # ndarray([598918, 2]) for ml-imdb
        return np.column_stack((rows, cols))

    def InfoNCE_agcl(self, anchor, positive, all_samples, temp):
        anchor = F.normalize(anchor, dim=1)
        positive = F.normalize(positive, dim=1)
        all_samples = F.normalize(all_samples, dim=1)
    
        pos_score = torch.sum(anchor * positive, dim=1)
        pos_score = torch.exp(pos_score / temp)

        ttl_score = torch.matmul(anchor, all_samples.t())
        ttl_score = torch.exp(ttl_score / temp).sum(dim=1)

        return -torch.log(pos_score / (ttl_score + 1e-12)).mean()

    def agcl(self, layer_embs, users, pos_items, temp, alpha):
        # layer 0
        user_emb_0, item_emb_0 = torch.split(layer_embs[0], [self.n_users, self.n_items])

        cl_user_loss = 0.0
        cl_item_loss = 0.0

        for k in range(1, len(layer_embs)):
            user_emb_k, item_emb_k = torch.split(layer_embs[k], [self.n_users, self.n_items])

            cl_user_loss = cl_user_loss + self.InfoNCE_agcl(
                anchor=item_emb_k[pos_items],
                positive=user_emb_0[users],
                all_samples=user_emb_0[users],
                temp=temp
            )

            cl_item_loss = cl_item_loss + self.InfoNCE_agcl(
                anchor=user_emb_k[users],
                positive=item_emb_0[pos_items],
                all_samples=item_emb_0[pos_items],
                temp=temp
            )

            user_emb_0, item_emb_0 = user_emb_k, item_emb_k

        return alpha * cl_user_loss + (1.0 - alpha) * cl_item_loss


    def forward(self, interaction):
        users = interaction[0]
        pos_items = interaction[1]
        neg_items = interaction[2]

        user_nodes = users
        pos_item_nodes = pos_items + self.n_users
        neg_item_nodes = neg_items + self.n_users

        self.v_rep, self.v_preference, v_layers = self.v_gcn(self.edge_index_dropv, self.edge_index, self.v_feat)
        self.t_rep, self.t_preference, t_layers = self.t_gcn(self.edge_index_dropt, self.edge_index, self.t_feat)
        self.id_rep, self.id_preference, _ = self.id_gcn(self.edge_index_dropt, self.edge_index, self.id_feat)

        agcl_v = self.agcl(v_layers, users, pos_items, temp=self.temp, alpha=self.alpha)
        agcl_t = self.agcl(t_layers, users, pos_items, temp=self.temp, alpha=self.alpha)

        layer_cl_loss = self.layer_agcl_weight * (agcl_v + agcl_t)

        representation = torch.cat((self.v_rep, self.t_rep), dim=1)
        guide_representation = torch.cat((self.id_rep, self.id_rep), dim=1)
        v_representation = torch.cat((self.v_rep, self.v_rep), dim=1)
        t_representation = torch.cat((self.t_rep, self.t_rep), dim=1)

        self.v_rep = torch.unsqueeze(self.v_rep, 2)
        self.t_rep = torch.unsqueeze(self.t_rep, 2)
        self.id_rep = torch.unsqueeze(self.id_rep, 2)

        user_rep = torch.cat((self.v_rep[:self.num_user], self.t_rep[:self.num_user]), dim=2)
        user_rep = self.weight_u.transpose(1, 2) * user_rep
        user_rep = torch.cat((user_rep[:, :, 0], user_rep[:, :, 1]), dim=1)


        guide_user_rep = torch.cat((self.id_rep[:self.num_user], self.id_rep[:self.num_user]), dim=2)
        guide_user_rep = torch.cat((guide_user_rep[:, :, 0], guide_user_rep[:, :, 1]), dim=1)

        v_user_rep = torch.cat((self.v_rep[:self.num_user], self.v_rep[:self.num_user]), dim=2)
        v_user_rep = torch.cat((v_user_rep[:, :, 0], v_user_rep[:, :, 1]), dim=1)

        t_user_rep = torch.cat((self.t_rep[:self.num_user], self.t_rep[:self.num_user]), dim=2)
        t_user_rep = torch.cat((t_user_rep[:, :, 0], t_user_rep[:, :, 1]), dim=1)

        item_rep = representation[self.num_user:]
        guide_item_rep = guide_representation[self.num_user:]
        v_item_rep = v_representation[self.num_user:]
        t_item_rep = t_representation[self.num_user:]

        h = self.buildItemGraph(item_rep)
        h_guide = self.buildItemGraph(guide_item_rep)
        h_v = self.buildItemGraph(v_item_rep)
        h_t = self.buildItemGraph(t_item_rep)

        user_rep = user_rep
        item_rep = item_rep + h

        guide_item_rep = guide_item_rep + h_guide
        v_item_rep = v_item_rep + h_v
        t_item_rep = t_item_rep + h_t

        self.user_rep = user_rep
        self.item_rep = item_rep
        self.result_embed = torch.cat((user_rep, item_rep), dim=0)

        self.guide_user_rep = guide_user_rep
        self.guide_item_rep = guide_item_rep
        self.result_embed_guide = torch.cat((guide_user_rep, guide_item_rep), dim=0)

        self.v_user_rep = v_user_rep
        self.v_item_rep = v_item_rep
        self.result_embed_v = torch.cat((v_user_rep, v_item_rep), dim=0)

        self.t_user_rep = t_user_rep
        self.t_item_rep = t_item_rep
        self.result_embed_t = torch.cat((t_user_rep, t_item_rep), dim=0)

        # calculate pos and neg scores
        user_tensor = self.result_embed[user_nodes]
        pos_item_tensor = self.result_embed[pos_item_nodes]
        neg_item_tensor = self.result_embed[neg_item_nodes]
        pos_scores = torch.sum(user_tensor * pos_item_tensor, dim=1)
        neg_scores = torch.sum(user_tensor * neg_item_tensor, dim=1)
        return pos_scores, neg_scores, layer_cl_loss

    def buildItemGraph(self, h):
        for i in range(self.n_layers):
            h = torch.sparse.mm(self.mm_adj, h)
        return h

    def fit_Gaussian_dis(self):
        r_var = torch.var(self.result_embed)
        r_mean = torch.mean(self.result_embed)
        g_var = torch.var(self.result_embed_guide)
        g_mean = torch.mean(self.result_embed_guide)
        v_var = torch.var(self.result_embed_v)
        v_mean = torch.mean(self.result_embed_v)
        t_var = torch.var(self.result_embed_t)
        t_mean = torch.mean(self.result_embed_t)
        return r_var, r_mean, g_var, g_mean, v_var, v_mean, t_var, t_mean

    def calculate_loss(self, interaction):
        user = interaction[0]
        pos_scores, neg_scores, layer_cl_loss = self.forward(interaction)
        loss_value = -torch.mean(torch.log2(torch.sigmoid(pos_scores - neg_scores)))

        reg_embedding_loss_v = (self.v_preference[user] ** 2).mean() if self.v_preference is not None else 0.0
        reg_embedding_loss_t = (self.t_preference[user] ** 2).mean() if self.t_preference is not None else 0.0
        reg_loss = self.reg_weight * (reg_embedding_loss_v + reg_embedding_loss_t)
        reg_loss += self.reg_weight * (self.weight_u ** 2).mean()

        r_var, r_mean, g_var, g_mean, v_var, v_mean, t_var, t_mean = self.fit_Gaussian_dis()

        align_loss = ((torch.abs(g_var - r_var) +
                         torch.abs(g_mean - r_mean)).mean() +
                        (torch.abs(g_var - v_var) +
                         torch.abs(g_mean - v_mean)).mean() +
                       (torch.abs(g_var - t_var) +
                        torch.abs(g_mean - t_mean)).mean() +
                      (torch.abs(r_var - v_var) +
                       torch.abs(r_mean - v_mean)).mean() +
                     (torch.abs(r_var - t_var) +
                      torch.abs(r_mean - t_mean)).mean() +
                    (torch.abs(v_var - t_var) +
                     torch.abs(v_mean - t_mean)).mean())
        align_loss = align_loss * self.align_weight
        
        return loss_value + reg_loss + align_loss + layer_cl_loss


    def full_sort_predict(self, interaction):
        user_tensor = self.result_embed[:self.n_users]
        item_tensor = self.result_embed[self.n_users:]

        temp_user_tensor = user_tensor[interaction[0], :]
        score_matrix = torch.matmul(temp_user_tensor, item_tensor.t())
        return score_matrix

    def topk_sample(self, k):
        user_graph_index = []
        count_num = 0
        user_weight_matrix = torch.zeros(len(self.user_graph_dict), k)
        tasike = []
        for i in range(k):
            tasike.append(0)
        for i in range(len(self.user_graph_dict)):
            if len(self.user_graph_dict[i][0]) < k:
                count_num += 1
                if len(self.user_graph_dict[i][0]) == 0:
                    # pdb.set_trace()
                    user_graph_index.append(tasike)
                    continue
                user_graph_sample = self.user_graph_dict[i][0][:k]
                user_graph_weight = self.user_graph_dict[i][1][:k]
                while len(user_graph_sample) < k:
                    rand_index = np.random.randint(0, len(user_graph_sample))
                    user_graph_sample.append(user_graph_sample[rand_index])
                    user_graph_weight.append(user_graph_weight[rand_index])
                user_graph_index.append(user_graph_sample)

                user_weight_matrix[i] = F.softmax(torch.tensor(user_graph_weight), dim=0)  # softmax
                continue
            user_graph_sample = self.user_graph_dict[i][0][:k]
            user_graph_weight = self.user_graph_dict[i][1][:k]

            user_weight_matrix[i] = F.softmax(torch.tensor(user_graph_weight), dim=0)  # softmax
            user_graph_index.append(user_graph_sample)

        # pdb.set_trace()
        return user_graph_index, user_weight_matrix

    def print_embd(self):
        return self.result_embed_v, self.result_embed_t


    def _row_normalize_sparse(self, indices, values, shape, eps: float = 1e-12):
        if not torch.is_tensor(indices):
            indices = torch.tensor(indices, dtype=torch.long, device=self.device)
        if not torch.is_tensor(values):
            values = torch.tensor(values, dtype=torch.float32, device=self.device)
        adj = torch.sparse_coo_tensor(indices, values, size=shape, device=self.device).coalesce()
        rows = adj.indices()[0]
        vals = adj.values()
        row_sum = torch.zeros(shape[0], device=self.device, dtype=vals.dtype)
        row_sum.index_add_(0, rows, vals)
        norm_vals = vals / (row_sum[rows] + eps)
        return torch.sparse_coo_tensor(adj.indices(), norm_vals, size=shape, device=self.device).coalesce()

    def _row_softmax_sparse(self, indices, values, shape, eps: float = 1e-12):
        if not torch.is_tensor(indices):
            indices = torch.tensor(indices, dtype=torch.long, device=self.device)
        if not torch.is_tensor(values):
            values = torch.tensor(values, dtype=torch.float32, device=self.device)
        adj = torch.sparse_coo_tensor(indices, values, size=shape, device=self.device).coalesce()
        rows = adj.indices()[0]
        vals = adj.values()
        try:
            max_per_row = torch.full((shape[0],), -1e9, device=self.device, dtype=vals.dtype)
            max_per_row.scatter_reduce_(0, rows, vals, reduce='amax', include_self=True)
        except Exception:
            import numpy as _np
            r_cpu = rows.detach().cpu().numpy()
            v_cpu = vals.detach().cpu().numpy()
            mp = _np.full((shape[0],), -1e9, dtype=_np.float32)
            for r, v in zip(r_cpu, v_cpu):
                if v > mp[r]: mp[r] = v
            max_per_row = torch.tensor(mp, device=self.device, dtype=vals.dtype)
        e = torch.exp(vals - max_per_row[rows])
        denom = torch.zeros(shape[0], device=self.device, dtype=vals.dtype)
        denom.index_add_(0, rows, e)
        soft = e / (denom[rows] + eps)
        return torch.sparse_coo_tensor(adj.indices(), soft, size=shape, device=self.device).coalesce()

    def _split_dct_bands(self, W, keep_ratio):
        D = W.size(1)
        k = max(1, int(D * keep_ratio))
        return W[:, :k], W[:, k:]

    def _haar_dwt_1d(self, x):
        x = x.float()

        if x.size(1) % 2 != 0:
            x = torch.cat([x, x[:, -1:].clone()], dim=1)

        x_even = x[:, 0::2]
        x_odd = x[:, 1::2]

        inv_sqrt2 = 1.0 / np.sqrt(2.0)
        lf = (x_even + x_odd) * inv_sqrt2
        hf = (x_even - x_odd) * inv_sqrt2
        return lf, hf

    def _knn_from_feat(self, F, k, shape):
        F = F / (F.norm(p=2, dim=1, keepdim=True) + 1e-12)
        sim = torch.mm(F, F.t())
        sim.fill_diagonal_(-1.0)
        _, nn_idx = torch.topk(sim, k, dim=-1)
        rows = torch.arange(nn_idx.size(0), device=F.device).unsqueeze(1).expand(-1, k).reshape(-1)
        cols = nn_idx.reshape(-1)
        idx = torch.stack([rows, cols], 0)
        val = torch.ones(rows.numel(), device=F.device, dtype=torch.float32)
        return self._row_normalize_sparse(idx, val, shape).coalesce()

    def build_item_semantic_graph(self, k: int = None, alpha_image: float = None):
        k = self.knn_k if k is None else int(k)
        alpha_image = self.mm_image_weight if alpha_image is None else float(alpha_image)
        parts = []
        # Vision
        if getattr(self, 'v_feat', None) is not None and hasattr(self, 'image_embedding'):
            emb = self.image_embedding.weight.detach()
            emb = emb / (emb.norm(p=2, dim=-1, keepdim=True) + 1e-12)
            sim = torch.mm(emb, emb.t())
            sim.fill_diagonal_(-1.0)
            _, knn_ind = torch.topk(sim, k, dim=-1)
            rows = torch.arange(knn_ind.shape[0], device=self.device).unsqueeze(1).expand(-1, k).reshape(-1)
            cols = knn_ind.reshape(-1)
            indices = torch.stack([rows, cols], dim=0)
            values = torch.ones(rows.numel(), device=self.device, dtype=torch.float32)
            G_img = self._row_normalize_sparse(indices, values, (self.n_items, self.n_items))
            parts.append(G_img)
            del sim
        # Text
        if getattr(self, 't_feat', None) is not None and hasattr(self, 'text_embedding'):
            emb = self.text_embedding.weight.detach()
            emb = emb / (emb.norm(p=2, dim=-1, keepdim=True) + 1e-12)
            sim = torch.mm(emb, emb.t())
            sim.fill_diagonal_(-1.0)
            _, knn_ind = torch.topk(sim, k, dim=-1)
            rows = torch.arange(knn_ind.shape[0], device=self.device).unsqueeze(1).expand(-1, k).reshape(-1)
            cols = knn_ind.reshape(-1)
            indices = torch.stack([rows, cols], dim=0)
            values = torch.ones(rows.numel(), device=self.device, dtype=torch.float32)
            G_txt = self._row_normalize_sparse(indices, values, (self.n_items, self.n_items))
            parts.append(G_txt)
            del sim
        if len(parts) == 0:
            raise RuntimeError("No modality features to build semantic graph.")
        G_sem = parts[0] if len(parts) == 1 else (alpha_image * parts[0] + (1.0 - alpha_image) * parts[1])
        return G_sem.coalesce()

    def build_item_semantic_graph_joint(self, k: int = None, alpha_image: float = None):
        k = self.knn_k if k is None else int(k)
        alpha_image = self.mm_image_weight if alpha_image is None else float(alpha_image)
        G_spatial = self.build_item_semantic_graph(k=k, alpha_image=alpha_image)
        G_spec = self.build_item_semantic_graph_spectral(k=k, alpha_image=alpha_image)
        lam = float(self.lambda_spec)
        G_sem_joint = (1.0 - lam) * G_spatial + lam * G_spec
        return G_sem_joint.coalesce()

    def build_item_semantic_graph_spectral(self, k: int = None, alpha_image: float = None):
        k = self.knn_k if k is None else int(k)
        alpha_image = self.mm_image_weight if alpha_image is None else float(alpha_image)
        shape = (self.n_items, self.n_items)

        v_lf = v_hf = t_lf = t_hf = None

        if getattr(self, 'v_feat', None) is not None:
            v_lf, v_hf = self._haar_dwt_1d(self.v_feat)

        if getattr(self, 't_feat', None) is not None:
            t_lf, t_hf = self._haar_dwt_1d(self.t_feat)

        if v_lf is not None and t_lf is not None:
            w_v = torch.cat((v_lf, v_hf), dim=1)
            w_t = torch.cat((t_lf, t_hf), dim=1)
            w_vt = torch.cat((w_v, w_t), dim=1)
        elif v_lf is not None:
            w_v = torch.cat((v_lf, v_hf), dim=1)
            w_vt = w_v
        elif t_lf is not None:
            w_t = torch.cat((t_lf, t_hf), dim=1)
            w_vt = w_t
        else:
            raise RuntimeError("No modality features available for spectral graph.")

        G_v_lf = G_v_hf = G_t_lf = G_t_hf = None

        if v_lf is not None:
            G_v_lf = self._knn_from_feat(v_lf, k, shape)
            G_v_hf = self._knn_from_feat(v_hf, k, shape)

        if t_lf is not None:
            G_t_lf = self._knn_from_feat(t_lf, k, shape)
            G_t_hf = self._knn_from_feat(t_hf, k, shape)

        G_mix = self._knn_from_feat(w_vt, k, shape)

        def _sum(A, B, ai):
            if A is None:
                return B
            if B is None:
                return A
            return ai * A + (1.0 - ai) * B

        G_lf = _sum(G_v_lf, G_t_lf, alpha_image)
        G_hf = _sum(G_v_hf, G_t_hf, alpha_image)

        G_spec = None
        if G_lf is not None:
            G_spec = self.beta_lf * G_lf if G_spec is None else G_spec + self.beta_lf * G_lf
        if G_hf is not None:
            G_spec = self.beta_hf * G_hf if G_spec is None else G_spec + self.beta_hf * G_hf
        if G_mix is not None:
            G_spec = self.beta_mix * G_mix if G_spec is None else G_spec + self.beta_mix * G_mix

        if G_spec is None:
            raise RuntimeError("No modality to build spectral semantic graph.")

        return G_spec.coalesce()

    def build_item_int_graph(self, topk: int = 100):
        # 获取交互矩阵
        ui = self.dataset.inter_matrix(form='coo').astype(np.float32)
        R = ui.tocsr()
        C = (R.T @ R).tocsr().astype(np.float32)
        C.setdiag(0.0)
        C.eliminate_zeros()
        rows, cols, vals = [], [], []
        n = C.shape[0]
        for i in range(n):
            start, end = C.indptr[i], C.indptr[i + 1]
            if start == end: continue
            row_idx = C.indices[start: end]
            row_val = C.data[start:end]
            if row_idx.size > topk:
                loc = np.argpartition(row_val, -topk)[-topk:]
                row_idx = row_idx[loc]
                row_val = row_val[loc]
            rows.extend([i] * row_idx.size)
            cols.extend(row_idx.tolist())
            vals.extend(row_val.tolist())
        if len(rows) == 0:
            indices = torch.empty((2, 0), dtype=torch.long, device=self.device)
            values = torch.empty((0,), dtype=torch.float32, device=self.device)
            return torch.sparse_coo_tensor(indices, values, size=(self.n_items, self.n_items), device=self.device)
        indices = torch.tensor([rows, cols], dtype=torch.long, device=self.device)
        values = torch.tensor(vals, dtype=torch.float32, device=self.device)
        return self._row_softmax_sparse(indices, values, (self.n_items, self.n_items)).coalesce()

    def build_and_cache_item_graphs_schemeA(self, k_sem, k_co, alpha_item_co, cache_dir):
        os.makedirs(cache_dir, exist_ok=True)
        fused_path = os.path.join(cache_dir, 'mm_adj_{}.pt'.format(self.knn_k))

        G_sem = self.build_item_semantic_graph_joint(k=k_sem, alpha_image=self.mm_image_weight)
        G_co = self.build_item_int_graph(topk=k_co)

        if self.enable_spec_gate:
            with torch.no_grad():
                if getattr(self, 'v_feat', None) is not None and getattr(self, 't_feat', None) is not None:
                    v_lf, v_hf = self._haar_dwt_1d(self.v_feat)
                    t_lf, t_hf = self._haar_dwt_1d(self.t_feat)
                    lf = torch.cat([v_lf, t_lf], dim=1)
                    full = torch.cat([v_lf, v_hf, t_lf, t_hf], dim=1)
                elif getattr(self, 'v_feat', None) is not None:
                    v_lf, v_hf = self._haar_dwt_1d(self.v_feat)
                    lf = v_lf
                    full = torch.cat([v_lf, v_hf], dim=1)
                elif getattr(self, 't_feat', None) is not None:
                    t_lf, t_hf = self._haar_dwt_1d(self.t_feat)
                    lf = t_lf
                    full = torch.cat([t_lf, t_hf], dim=1)
                else:
                    raise RuntimeError("No modality features available.")

                rho = lf.norm(p=2, dim=1) / (full.norm(p=2, dim=1) + 1e-12)
            G_co = G_co.coalesce()
            ii = G_co.indices()
            vv = G_co.values()
            gate = torch.exp(- (rho[ii[0]] - rho[ii[1]]).abs() / max(1e-6, self.spec_gate_tau))
            G_co = torch.sparse_coo_tensor(ii, vv * gate, size=G_co.shape, device=G_co.device).coalesce()

        mm_adj = (alpha_item_co * G_co + (1.0 - alpha_item_co) * G_sem).coalesce().to(self.device)
        torch.save(mm_adj.cpu(), fused_path)
        return mm_adj

class GCN(torch.nn.Module):
    def __init__(self, datasets, batch_size, num_user, num_item, dim_id, aggr_mode,
                 dim_latent=None, device=None, features=None):
        super(GCN, self).__init__()
        self.batch_size = batch_size
        self.num_user = num_user
        self.num_item = num_item
        self.datasets = datasets
        self.dim_id = dim_id
        self.dim_feat = features.size(1)
        self.dim_latent = dim_latent
        self.aggr_mode = aggr_mode
        self.device = device

        if self.dim_latent:
            self.preference = nn.Parameter(nn.init.xavier_normal_(torch.tensor(
                np.random.randn(num_user, self.dim_latent), dtype=torch.float32, requires_grad=True),
                gain=1).to(self.device))
            self.MLP = nn.Linear(self.dim_feat, 4 * self.dim_latent)
            self.MLP_1 = nn.Linear(4 * self.dim_latent, self.dim_latent)
            self.conv_embed_1 = Base_gcn(self.dim_latent, self.dim_latent, aggr=self.aggr_mode)

        else:
            self.preference = nn.Parameter(nn.init.xavier_normal_(torch.tensor(
                np.random.randn(num_user, self.dim_feat), dtype=torch.float32, requires_grad=True),
                gain=1).to(self.device))
            self.conv_embed_1 = Base_gcn(self.dim_latent, self.dim_latent, aggr=self.aggr_mode)

    def forward(self, edge_index_drop, edge_index, features, perturbed=False):
        temp_features = self.MLP_1(F.leaky_relu(self.MLP(features))) if self.dim_latent else features
        x = torch.cat((self.preference, temp_features), dim=0).to(self.device)
        x = F.normalize(x).to(self.device)

        h = self.conv_embed_1(x, edge_index)
        h_1 = self.conv_embed_1(h, edge_index)
        x_hat = x + h + h_1
        layers_emb = [x, h, h_1]

        return x_hat, self.preference, layers_emb


class Base_gcn(MessagePassing):
    def __init__(self, in_channels, out_channels, normalize=True, bias=True, aggr='add', **kwargs):
        super(Base_gcn, self).__init__(aggr=aggr, **kwargs)
        self.aggr = aggr
        self.in_channels = in_channels
        self.out_channels = out_channels

    def forward(self, x, edge_index, size=None):
        # pdb.set_trace()
        if size is None:
            edge_index, _ = remove_self_loops(edge_index)
            # edge_index, _ = add_self_loops(edge_index, num_nodes=x.size(0))
        x = x.unsqueeze(-1) if x.dim() == 1 else x
        # pdb.set_trace()
        return self.propagate(edge_index, size=(x.size(0), x.size(0)), x=x)

    def message(self, x_j, edge_index, size):
        if self.aggr == 'add':
            # pdb.set_trace()
            row, col = edge_index
            deg = degree(row, size[0], dtype=x_j.dtype)
            deg_inv_sqrt = deg.pow(-0.5)
            norm = deg_inv_sqrt[row] * deg_inv_sqrt[col]
            return norm.view(-1, 1) * x_j
        return x_j

    def update(self, aggr_out):
        return aggr_out

    def __repr(self):
        return '{}({},{})'.format(self.__class__.__name__, self.in_channels, self.out_channels)